UPDATE tools SET faq = $x$[{"q": "מהו Fireflies.ai?", "a": "Fireflies.ai היא פלטפורמת בינה לפגישות שמקליטה, מתמללת ומסכמת פגישות אוטומטית, עם תמלולים ניתנים לחיפוש, סיכומי פגישה מבוססי AI וניתוח שיחות. היא כוללת גם Fireflies Talk, כלי הכתבה קולית חינמי וללא הגבלה לכל אפליקציה במחשבי Mac ו-Windows."}, {"q": "האם Fireflies.ai חינמי?", "a": "ל-Fireflies.ai יש תוכנית חינמית עם 400 דקות אחסון לצוות בחודש, 20 קרדיטים ל-AI, סיכומי AI מוגבלים, והכתבת Fireflies Talk ללא הגבלה. Pro עולה 10$ למשתמש בחודש בחיוב שנתי (או 18$ בחיוב חודשי) עם 8,000 דקות אחסון למשתמש. Business עולה 19$ למשתמש בחודש בחיוב שנתי (או 29$ בחיוב חודשי) עם אחסון ללא הגבלה."}]$x$::jsonb
