UPDATE tools SET faq = $x$[{"a": "Bubble — это no-code конструктор приложений для создания веб-приложений с базами данных, логикой и пользовательскими взаимодействиями. Webflow — это no-code конструктор сайтов, ориентированный на дизайн и CMS. Bubble создаёт приложения, Webflow создаёт сайты.", "q": "В чём разница между Bubble и Webflow?"}, {"a": "В Webflow есть CMS (система управления контентом) для структурированного контента, такого как записи блога и списки товаров. Это не полноценная база данных приложения — для пользовательских данных, транзакций или сложной логики потребуется Bubble или собственный бэкенд.", "q": "Есть ли в Webflow база данных?"}, {"a": "Тариф сайта Starter и Starter Workspace в Webflow бесплатны, у Bubble также есть бесплатный тариф. В остальном компании взимают плату по-разному: Webflow выставляет отдельный счёт за тариф сайта (Basic начинается от $15/мес при годовой оплате, $25/мес при помесячной) и отдельный платный тариф Workspace, включающий AI-кредиты, плюс дополнительные места и надстройки, тогда как Bubble взимает плату за нагрузку приложения. Прямое сравнение стоимости зависит от того, какие тарифы и надстройки вы комбинируете.", "q": "Что дешевле — Bubble или Webflow?"}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'ru';

