UPDATE tools SET faq = $x$[{"a": "Bubble é um construtor de aplicativos sem código — é voltado para a criação de aplicativos web com bancos de dados, lógica e interações de usuário. Webflow é um construtor de sites sem código focado em design e CMS. Bubble constrói aplicativos; Webflow constrói sites.", "q": "Qual é a diferença entre Bubble e Webflow?"}, {"a": "O Webflow tem um CMS (Content Management System) para conteúdo estruturado, como posts de blog e listagens de produtos. Não é um banco de dados de aplicação completo — para dados de usuário, transações ou lógica complexa, seria necessário o Bubble ou um backend personalizado.", "q": "O Webflow tem banco de dados?"}, {"a": "O plano de site Starter e o Starter Workspace do Webflow são ambos gratuitos, e o Bubble também tem um plano gratuito. Além disso, os dois cobram de forma diferente: o Webflow fatura separadamente um plano de site (o Basic começa em US$ 15/mês na cobrança anual, US$ 25/mês na cobrança mensal) e um plano pago separado de Workspace que inclui créditos de IA, além de vagas e add-ons opcionais, enquanto o Bubble cobra por carga de trabalho do aplicativo. Uma comparação direta de custo depende de quais níveis e add-ons são combinados.", "q": "Qual é mais barato — Bubble ou Webflow?"}]$x$::jsonb
 WHERE slug = 'webflow' AND lang = 'pt';

