UPDATE tools SET faq = $x$[{"a": "Relume is an AI tool that generates website briefs, sitemaps, and wireframes from a text description, with a component library for Webflow, Figma, and React. It also has an in-beta Publish feature that can host the finished site directly on a custom domain, alongside the original export-to-Webflow-or-Figma workflow.", "q": "What is Relume?"}, {"a": "Relume's core strength is the AI-driven planning stage: briefs, sitemaps, and wireframes, plus a large component library for Webflow, Figma, and React. Its Export path hands off to those platforms for final build. Relume now also has a Publish path in beta for hosting a live site directly, which narrows the gap with tools like Framer, but Publish is newer and less established than Relume's export workflow.", "q": "What is the difference between Relume and Framer?"}, {"a": "Yes, both of Relume's products have a free plan. Build with Relume's free plan requires no card and includes limited shared AI usage with free hosting on a relume.live subdomain (up to 1,500 page views and 20 form submissions per month). Site Builder's free plan includes 30 Webflow components, 30 React components, and 1,000+ Figma components. Paid plans start from $14/month for Build with Relume Pro and from $18/month for Site Builder Starter.", "q": "Is Relume free?"}, {"a": "Yes. Relume's component library and generated wireframes can be exported to Figma, as well as to Webflow and React (Tailwind CSS and shadcn/ui), letting teams choose the platform that fits their build process.", "q": "Does Relume work with Figma?"}]$x$::jsonb
 WHERE slug = 'relume' AND lang = 'en';

