UPDATE tools SET faq = $x$[{"a": "Relume es una herramienta de IA que genera briefs, mapas del sitio y wireframes a partir de una descripción en texto, con una biblioteca de componentes para Webflow, Figma y React. También tiene una función de Publicación en fase beta que puede alojar el sitio terminado directamente en un dominio personalizado, junto con el flujo de trabajo original de exportación a Webflow o Figma.", "q": "¿Qué es Relume?"}, {"a": "La principal fortaleza de Relume es la etapa de planificación impulsada por IA: briefs, mapas del sitio y wireframes, además de una amplia biblioteca de componentes para Webflow, Figma y React. Su ruta de Exportación traspasa el proyecto a esas plataformas para la construcción final. Relume ahora también tiene una ruta de Publicación en beta para alojar un sitio en vivo directamente, lo que reduce la diferencia con herramientas como Framer, pero Publish es más reciente y menos establecido que el flujo de exportación de Relume.", "q": "¿Cuál es la diferencia entre Relume y Framer?"}, {"a": "Sí, ambos productos de Relume tienen un plan gratuito. El plan gratuito de Build with Relume no requiere tarjeta e incluye uso compartido limitado de IA con alojamiento gratuito en un subdominio relume.live (hasta 1.500 visitas de página y 20 envíos de formulario al mes). El plan gratuito de Site Builder incluye 30 componentes de Webflow, 30 componentes de React y más de 1.000 componentes de Figma. Los planes de pago comienzan desde $14/mes para Build with Relume Pro y desde $18/mes para Site Builder Starter.", "q": "¿Es gratis Relume?"}, {"a": "Sí. La biblioteca de componentes y los wireframes generados por Relume se pueden exportar a Figma, así como a Webflow y React (Tailwind CSS y shadcn/ui), lo que permite a los equipos elegir la plataforma que mejor se adapte a su proceso de construcción.", "q": "¿Funciona Relume con Figma?"}]$x$::jsonb
 WHERE slug = 'relume' AND lang = 'es';

