UPDATE tools SET faq = $x$[{"a": "Relume הוא כלי AI שמייצר תדריכי אתרים, מפות אתר ושלדי עמודים מתוך תיאור טקסטואלי, עם ספריית רכיבים ל-Webflow, Figma ו-React. יש לו גם פיצ'ר Publish בגרסת בטא שיכול לארח את האתר המוגמר ישירות על דומיין מותאם אישית, לצד זרימת העבודה המקורית של ייצוא ל-Webflow או Figma.", "q": "מהו Relume?"}, {"a": "החוזק המרכזי של Relume הוא שלב התכנון מבוסס ה-AI: תדריכים, מפות אתר ושלדי עמודים, בתוספת ספריית רכיבים גדולה ל-Webflow, Figma ו-React. נתיב ה-Export שלו מעביר את הפרויקט לפלטפורמות אלו לבנייה הסופית. ל-Relume יש כעת גם נתיב Publish בבטא לאירוח אתר חי ישירות, מה שמצמצם את הפער מול כלים כמו Framer, אך Publish חדש יותר ופחות מבוסס מזרימת העבודה של הייצוא ב-Relume.", "q": "מה ההבדל בין Relume ל-Framer?"}, {"a": "כן, לשני המוצרים של Relume יש מסלול חינמי. המסלול החינמי של Build with Relume אינו דורש כרטיס אשראי וכולל שימוש AI משותף מוגבל עם אירוח חינם בסאב-דומיין relume.live (עד 1,500 צפיות בעמוד ו-20 שליחות טפסים בחודש). המסלול החינמי של Site Builder כולל 30 רכיבי Webflow, 30 רכיבי React, ויותר מ-1,000 רכיבי Figma. המסלולים בתשלום מתחילים מ-14$/חודש עבור Build with Relume Pro ומ-18$/חודש עבור Site Builder Starter.", "q": "האם Relume חינמי?"}, {"a": "כן. ספריית הרכיבים ושלדי העמודים שנוצרים על ידי Relume ניתנים לייצוא ל-Figma, וכן ל-Webflow ו-React (Tailwind CSS ו-shadcn/ui), מה שמאפשר לצוותים לבחור את הפלטפורמה שמתאימה לתהליך הבנייה שלהם.", "q": "האם Relume עובד עם Figma?"}]$x$::jsonb
 WHERE slug = 'relume' AND lang = 'he';

