UPDATE tools SET faq = $x$[{"a": "Relume est un outil d'IA qui génère des briefs de sites web, des sitemaps et des wireframes à partir d'une description textuelle, avec une bibliothèque de composants pour Webflow, Figma et React. Il dispose également d'une fonctionnalité Publish en bêta qui peut héberger le site finalisé directement sur un domaine personnalisé, en plus du flux de travail original d'export vers Webflow ou Figma.", "q": "Qu'est-ce que Relume ?"}, {"a": "La principale force de Relume est l'étape de planification pilotée par l'IA : briefs, sitemaps et wireframes, ainsi qu'une vaste bibliothèque de composants pour Webflow, Figma et React. Son parcours Export transfère le travail vers ces plateformes pour la construction finale. Relume dispose désormais aussi d'un parcours Publish en bêta pour héberger un site en direct directement, ce qui réduit l'écart avec des outils comme Framer, mais Publish est plus récent et moins établi que le flux de travail d'export de Relume.", "q": "Quelle est la différence entre Relume et Framer ?"}, {"a": "Oui, les deux produits de Relume ont un plan gratuit. Le plan gratuit de Build with Relume ne nécessite aucune carte et inclut un usage IA partagé limité avec hébergement gratuit sur un sous-domaine relume.live (jusqu'à 1 500 pages vues et 20 soumissions de formulaire par mois). Le plan gratuit de Site Builder inclut 30 composants Webflow, 30 composants React et plus de 1 000 composants Figma. Les plans payants commencent à 14 $/mois pour Build with Relume Pro et à 18 $/mois pour Site Builder Starter.", "q": "Relume est-il gratuit ?"}, {"a": "Oui. La bibliothèque de composants de Relume et les wireframes générés peuvent être exportés vers Figma, ainsi que vers Webflow et React (Tailwind CSS et shadcn/ui), permettant aux équipes de choisir la plateforme adaptée à leur processus de construction.", "q": "Relume fonctionne-t-il avec Figma ?"}]$x$::jsonb
 WHERE slug = 'relume' AND lang = 'fr';

