UPDATE tools SET faq = $x$[{"a": "Relume é uma ferramenta de IA que gera briefings, mapas do site e wireframes a partir de uma descrição em texto, com uma biblioteca de componentes para Webflow, Figma e React. Também tem um recurso de Publicação em beta que pode hospedar o site finalizado diretamente em um domínio personalizado, junto com o fluxo de trabalho original de exportação para Webflow ou Figma.", "q": "O que é Relume?"}, {"a": "O principal ponto forte do Relume é a etapa de planejamento orientada por IA: briefings, mapas do site e wireframes, além de uma grande biblioteca de componentes para Webflow, Figma e React. Seu caminho de Export transfere o trabalho para essas plataformas para a construção final. O Relume agora também tem um caminho de Publicação em beta para hospedar um site ao vivo diretamente, o que reduz a diferença em relação a ferramentas como Framer, mas o Publish é mais novo e menos consolidado do que o fluxo de exportação do Relume.", "q": "Qual é a diferença entre Relume e Framer?"}, {"a": "Sim, ambos os produtos do Relume têm um plano gratuito. O plano gratuito do Build with Relume não exige cartão e inclui uso compartilhado de IA limitado com hospedagem gratuita em um subdomínio relume.live (até 1.500 visualizações de página e 20 envios de formulário por mês). O plano gratuito do Site Builder inclui 30 componentes Webflow, 30 componentes React e mais de 1.000 componentes Figma. Os planos pagos começam a partir de US$ 14/mês para o Build with Relume Pro e a partir de US$ 18/mês para o Site Builder Starter.", "q": "O Relume é gratuito?"}, {"a": "Sim. A biblioteca de componentes e os wireframes gerados pelo Relume podem ser exportados para o Figma, assim como para Webflow e React (Tailwind CSS e shadcn/ui), permitindo que as equipes escolham a plataforma que se encaixa em seu processo de construção.", "q": "O Relume funciona com Figma?"}]$x$::jsonb
 WHERE slug = 'relume' AND lang = 'pt';

