 WHERE slug = 'n8n' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is the difference between Make and n8n?", "a": "Make is a cloud-based visual automation platform designed for non-technical users with 1,500+ connectors. n8n is an open-source automation tool that can be self-hosted, offering more technical flexibility and code control. Make is easier; n8n is more powerful for developers."}, {"q": "Is n8n free?", "a": "n8n is free to self-host via the open-source Community Edition, with unlimited executions and all integrations. The cloud version has no ongoing free plan, only a limited free trial (1,000 executions, no credit card). Paid cloud tiers (Starter, Pro, Business) are billed annually in euros, and Enterprise pricing is custom. Self-hosting requires technical knowledge to set up and maintain."}]$x$::jsonb
 WHERE slug = 'n8n' AND lang = 'en';

