 WHERE slug = 'n8n' AND lang = 'es';

UPDATE tools SET faq = $x$[{"q": "¿Cuál es la diferencia entre Make y n8n?", "a": "Make es una plataforma de automatización visual basada en la nube diseñada para usuarios no técnicos, con más de 1500 conectores. n8n es una herramienta de automatización de código abierto que puede autoalojarse, lo que ofrece mayor flexibilidad técnica y control de código. Make es más sencillo; n8n es más potente para desarrolladores."}, {"q": "¿Es gratuito n8n?", "a": "n8n es gratuito para autoalojar mediante la Community Edition de código abierto, con ejecuciones ilimitadas y todas las integraciones. La versión en la nube no tiene un plan gratuito continuo, solo una prueba gratuita limitada (1000 ejecuciones, sin tarjeta de crédito). Los niveles de pago en la nube (Starter, Pro, Business) se facturan anualmente en euros, y los precios de Enterprise son personalizados. El autoalojamiento requiere conocimientos técnicos para su configuración y mantenimiento."}]$x$::jsonb
