UPDATE tools SET faq = $x$[{"q": "Was ist der Unterschied zwischen Make und n8n?", "a": "Make ist eine cloudbasierte visuelle Automatisierungsplattform für nicht-technische Nutzer mit über 1.500 Konnektoren. n8n ist ein Open-Source-Automatisierungstool, das selbst gehostet werden kann und mehr technische Flexibilität und Codekontrolle bietet. Make ist einfacher zu bedienen; n8n ist für Entwickler leistungsfähiger."}, {"q": "Ist n8n kostenlos?", "a": "n8n lässt sich kostenlos über die Open-Source-Community-Edition selbst hosten, mit unbegrenzten Ausführungen und allen Integrationen. Die Cloud-Version hat keinen dauerhaft kostenlosen Plan, sondern nur eine begrenzte kostenlose Testphase (1.000 Ausführungen, keine Kreditkarte erforderlich). Kostenpflichtige Cloud-Stufen (Starter, Pro, Business) werden jährlich in Euro abgerechnet, und die Enterprise-Preise sind individuell. Selbst-Hosting erfordert technisches Wissen zur Einrichtung und Wartung."}]$x$::jsonb
