UPDATE tools SET faq = $x$[{"q": "מה ההבדל בין Make לבין n8n?", "a": "Make היא פלטפורמת אוטומציה חזותית מבוססת ענן המיועדת למשתמשים לא טכניים עם מעל 1,500 מחברים. n8n הוא כלי אוטומציה בקוד פתוח שניתן לארח עצמאית, המציע גמישות טכנית רבה יותר ושליטה בקוד. Make קלה יותר; n8n חזקה יותר עבור מפתחים."}, {"q": "האם n8n חינמית?", "a": "n8n חינמית לאירוח עצמי דרך גרסת ה-Community בקוד פתוח, עם הרצות ללא הגבלה וכל השילובים. לגרסת הענן אין תוכנית חינמית מתמשכת, רק ניסיון חינמי מוגבל (1,000 הרצות, ללא צורך בכרטיס אשראי). דרגות הענן בתשלום (Starter, Pro, Business) מחויבות שנתית ביורו, ותמחור Enterprise הוא בהתאמה אישית. אירוח עצמי דורש ידע טכני להתקנה ותחזוקה."}]$x$::jsonb
