UPDATE tools SET faq = $x$[{"q": "Was ist Retool?", "a": "Retool ist eine Plattform zum Erstellen interner Tools. Ihr App-Builder ist jetzt KI-nativ — beschreiben Sie die benötigte App, und Retool generiert eine funktionierende Version — während ein klassischer Drag-and-Drop-Builder für bestehende Apps verfügbar bleibt. Entwickler verbinden sich mit Datenbanken und APIs, sodass Apps anschließend Aktionen ausführen können, etwa Datenbankeinträge bearbeiten, Workflows auslösen oder Daten senden, statt sie nur anzuzeigen."}, {"q": "Ist Retool kostenlos?", "a": "Retool bietet einen kostenlosen Plan für bis zu 5 Nutzer, der jedoch limitiert ist: 500 Workflow-Ausführungen, 5 GB Datenbankkapazität, 5 GB Dateispeicher, 250 KI-Credits und bis zu 20 Agentenstunden pro Monat. Kostenpflichtige Pläne trennen Builder-Sitzplätze und Internal-User-Sitzplätze: Team-Builder-Sitzplätze kosten 10 $/Nutzer/Monat bei jährlicher Abrechnung (12 $/Nutzer/Monat bei monatlicher Abrechnung), Business-Builder-Sitzplätze kosten 50 $/Nutzer/Monat jährlich (65 $ monatlich), und Enterprise-Preise sind individuell."}, {"q": "Ist Retool ein No-Code-Tool?", "a": "Retool ist eher Low-Code als No-Code, selbst mit seinem neuen KI-nativen Builder. Es profitiert weiterhin von technischem Wissen — Verbindung zu Datenbanken, Schreiben von SQL-Abfragen und Verständnis von APIs — für alles, was über die anfangs generierte App hinausgeht. Es ist für Entwickler und technische Teams konzipiert, nicht für Geschäftsanwender ohne technischen Hintergrund."}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'de';

UPDATE tools SET best_for = $x$Создание внутренних AI-инструментов и приложений поверх баз данных и API$x$
 WHERE slug = 'retool-ai' AND lang = 'ru';

UPDATE tools SET description = $x$Платформа для создания внутренних бизнес-инструментов — дашбордов, админ-панелей, редакторов данных — теперь построенная вокруг AI-native конструктора приложений, который генерирует рабочее приложение по описанию, плюс классический конструктор drag-and-drop и агентные рабочие процессы. Бесплатный план охватывает до 5 пользователей; платные тарифы разделяют места Builder и Internal User, оплата помесячно или ежегодно (места Team Builder $10/мес при ежегодной оплате или $12/мес при помесячной; места Business Builder $50/мес при ежегодной оплате или $65/мес при помесячной).$x$
 WHERE slug = 'retool-ai' AND lang = 'ru';

UPDATE tools SET description_long = $x$Retool — это платформа для создания внутренних бизнес-приложений — админ-панелей, дашбордов данных, инструментов поддержки клиентов и операционных рабочих процессов — путём прямого подключения к базам данных и API.

Retool полностью перестроил свой конструктор приложений, сделав его AI-native: вместо начала с пустого холста пользователи описывают нужное приложение, и Retool генерирует рабочую версию. Предыдущий конструктор drag-and-drop по-прежнему существует и теперь называется классическим конструктором приложений, и созданные с его помощью приложения продолжают работать. В октябре 2026 года Retool также представил агентный каркас (agent harness), цель которого — дать каждому сотруднику управляемого агента внутри Slack, Microsoft Teams и Google Chat, с контролируемым компанией шлюзом, обеспечивающим ограничения на инструменты, данные и модели. Этот агентный каркас доступен только в раннем доступе, по списку ожидания, и Retool пока не опубликовал цены на него.

Помимо нового конструктора, Retool AI позволяет командам встраивать компоненты на базе LLM в приложения: автозаполнение форм с помощью AI, суммаризацию данных с помощью AI, AI-чатботов внутри внутренних дашбордов и агентные рабочие процессы, объединяющие несколько шагов с участием AI с контрольными точками одобрения человеком. Платформа подключается к источникам данных, включая Postgres, MySQL, Snowflake, MongoDB, REST API и GraphQL, и поддерживает JavaScript и Python для пользовательской логики, а также журналы аудита и управление доступом на основе ролей.

Бесплатный план Retool охватывает до 5 пользователей с неограниченным количеством веб- и мобильных приложений, но имеет лимиты: 500 запусков рабочих процессов в месяц, 5 ГБ ёмкости базы данных, 5 ГБ хранилища файлов, 250 AI-кредитов в месяц и до 20 часов работы агентов в месяц. Платные планы разделяют места Builder (люди, создающие приложения) и более дешёвые места Internal User (люди, которые только используют их). Места Team Builder стоят $10 за пользователя в месяц при ежегодной оплате или $12 при помесячной, с 1000 AI-кредитов в месяц (750 базовых плюс 250 бонусных) и 5000 запусков рабочих процессов; места Team Internal User стоят $5 за пользователя в месяц при ежегодной оплате или $7 при помесячной. Места Business Builder стоят $50 за пользователя в месяц при ежегодной оплате или $65 при помесячной, с 3000 AI-кредитов в месяц (1500 базовых плюс 1500 бонусных); места Business Internal User стоят $15 за пользователя в месяц при ежегодной оплате или $18 при помесячной, а внешние пользователи бесплатны до 50 человек, затем оплата по уровням от $8 до $10 за пользователя. Цены Enterprise индивидуальны и включают 1000 AI-кредитов на каждого builder плюс 4000 кредитов в общем пуле. Retool Agents оплачиваются отдельно почасово по тарифам, которые варьируются в зависимости от модели, с бесплатным лимитом до 20 часов работы агентов в месяц, включённым во все тарифы; выполнение агентов приостанавливается, когда эти бесплатные часы заканчиваются, до тех пор пока аккаунт не будет обновлён.

Retool оптимизирован для внутренних инструментов — он не подходит для создания клиентских продакшн-приложений. Использование агентов оплачивается почасово сверх платы за места, что может затруднить прогнозирование общих расходов для команд, активно использующих агентов, а новый агентный каркас ещё не доступен в общем доступе. Конструктор, даже в своей AI-native форме, выигрывает от знакомства с концепциями данных (запросы, преобразования) для всего, что выходит за рамки сгенерированной отправной точки.

Лучше всего подходит для операционных, продуктовых и инженерных команд в стартапах и крупных компаниях, которым нужно создавать пользовательские внутренние инструменты поверх существующих источников данных — особенно для тех, кто добавляет AI-ассистированные рабочие процессы или общекорпоративных агентов к существующим бизнес-операциям.$x$
 WHERE slug = 'retool-ai' AND lang = 'ru';

UPDATE tools SET pros = ARRAY[$x$AI-native конструктор приложений генерирует рабочее приложение по описанию, при этом классический конструктор drag-and-drop остаётся доступным для существующих приложений$x$, $x$Подключается напрямую к базам данных (Postgres, MySQL, Snowflake, MongoDB) и API (REST, GraphQL) без необходимости пользовательской разработки бэкенда$x$, $x$AI-компоненты обеспечивают функции на базе LLM во внутренних приложениях без пользовательской разработки AI$x$, $x$Бесплатный план для до 5 пользователей включает AI-кредиты и часы работы агентов, а не только базовое создание приложений$x$, $x$Контрольные точки одобрения человеком для рабочих процессов AI-агентов$x$]::text[]
 WHERE slug = 'retool-ai' AND lang = 'ru';

