UPDATE tools SET faq = $x$[{"q": "Что такое Retool?", "a": "Retool — это платформа для создания внутренних инструментов. Её конструктор приложений теперь AI-native — опишите нужное приложение, и Retool сгенерирует рабочую версию — при этом классический конструктор drag-and-drop остаётся доступным для существующих приложений. Разработчики подключаются к базам данных и API, после чего приложения могут выполнять действия, такие как редактирование записей в базе данных, запуск рабочих процессов или отправка данных, а не просто отображать их."}, {"q": "Retool бесплатен?", "a": "У Retool есть бесплатный план для до 5 пользователей, но он ограничен: 500 запусков рабочих процессов, 5 ГБ ёмкости базы данных, 5 ГБ хранилища файлов, 250 AI-кредитов и до 20 часов работы агентов в месяц. Платные планы разделяют места Builder и Internal User: места Team Builder стоят $10 за пользователя в месяц при ежегодной оплате ($12 за пользователя в месяц при помесячной), места Business Builder стоят $50 за пользователя в месяц при ежегодной оплате ($65 при помесячной), а цены Enterprise индивидуальны."}, {"q": "Retool — это инструмент без кода?", "a": "Retool скорее low-code, чем no-code, даже с новым AI-native конструктором. Он по-прежнему выигрывает от технических знаний — подключения к базам данных, написания SQL-запросов и понимания API — для всего, что выходит за рамки изначально сгенерированного приложения. Он разработан для разработчиков и технических команд, а не для бизнес-пользователей без технической подготовки."}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'ru';

