UPDATE tools SET faq = $x$[{"q": "Що таке Retool?", "a": "Retool — це платформа для створення внутрішніх інструментів. Її конструктор застосунків тепер AI-native — опишіть потрібний застосунок, і Retool згенерує робочу версію — тоді як класичний конструктор drag-and-drop залишається доступним для наявних застосунків. Розробники підключаються до баз даних і API, після чого застосунки можуть виконувати дії, як-от редагування записів бази даних, запуск робочих процесів або надсилання даних, а не лише відображати їх."}, {"q": "Чи Retool безплатний?", "a": "Retool має безплатний план для до 5 користувачів, але з обмеженнями: 500 запусків робочих процесів, 5 ГБ ємності бази даних, 5 ГБ сховища файлів, 250 кредитів AI та до 20 годин роботи агента на місяць. Платні плани розділяють місця Builder та Internal User: місця Team Builder коштують $10 на користувача на місяць за щорічної оплати ($12 на користувача на місяць за щомісячної), місця Business Builder — $50 на користувача на місяць за щорічної оплати ($65 за щомісячної), а ціни для Enterprise індивідуальні."}, {"q": "Чи Retool — інструмент без коду (no-code)?", "a": "Retool радше low-code, ніж no-code, навіть з новим AI-native конструктором. Він досі виграє від технічних знань — підключення до баз даних, написання SQL-запитів та розуміння API — для всього, що виходить за межі початкового згенерованого застосунку. Він розрахований на розробників і технічні команди, а не на бізнес-користувачів без технічної підготовки."}]$x$::jsonb
