UPDATE tools SET faq = $x$[{"q": "O que é Retool?", "a": "Retool é uma plataforma para criação de ferramentas internas. Seu criador de apps agora é nativo em IA — descreva o aplicativo de que precisa e a Retool gera uma versão funcional — enquanto um criador clássico de arrastar e soltar permanece disponível para apps existentes. Desenvolvedores se conectam a bancos de dados e APIs, e então os aplicativos podem realizar ações como editar registros de banco de dados, acionar fluxos de trabalho ou enviar dados, em vez de apenas exibi-los."}, {"q": "A Retool é gratuita?", "a": "A Retool tem um plano gratuito para até 5 usuários, mas ele é medido: 500 execuções de workflow, 5GB de capacidade de banco de dados, 5GB de armazenamento de arquivos, 250 créditos de IA e até 20 horas de agente por mês. Os planos pagos separam assentos de Builder e de Internal User: os assentos Team Builder custam $10/usuário/mês cobrados anualmente ($12/usuário/mês cobrados mensalmente), os assentos Business Builder custam $50/usuário/mês anualmente ($65 mensalmente), e o preço Enterprise é personalizado."}, {"q": "A Retool é uma ferramenta no-code?", "a": "A Retool é low-code em vez de no-code, mesmo com seu novo criador nativo em IA. Ela ainda se beneficia de conhecimento técnico — conectar-se a bancos de dados, escrever consultas SQL e entender APIs — para qualquer coisa além do app inicial gerado. Foi projetada para desenvolvedores e equipes técnicas, não para usuários de negócios sem conhecimento técnico."}]$x$::jsonb
 WHERE slug = 'retool-ai' AND lang = 'pt';

