UPDATE tools SET choose_if = $x$["🔬 Realizas revisiones sistemáticas de literatura y necesitas filtrar miles de artículos", "📊 Quieres extracción de datos estructurados en tablas en lugar de solo resultados de búsqueda", "🔗 Necesitas citas verificables vinculadas a cada afirmación resumida", "🛠️ Quieres integrar la búsqueda y extracción académica en tus propias herramientas mediante la API", "🏥 Necesitas cobertura de ensayos clínicos junto con artículos publicados"]$x$::jsonb
 WHERE slug = 'elicit' AND lang = 'es';

UPDATE tools SET faq = $x$[{"a": "Elicit es un asistente de investigación de IA diseñado para revisiones sistemáticas de literatura. Busca en bases de datos académicas, filtra artículos por relevancia y extrae datos estructurados en tablas, automatizando las partes más laboriosas de la investigación académica. Lo utilizan investigadores, científicos y equipos de síntesis de evidencia.", "q": "¿Qué es Elicit?"}, {"a": "Elicit está diseñado para revisiones sistemáticas: extrae datos estructurados de los artículos en tablas para metaanálisis. Consensus está diseñado para respuestas rápidas: sintetiza hallazgos de artículos en respuestas en lenguaje sencillo con un medidor de consenso. Elicit sirve para flujos de trabajo de investigación profunda; Consensus, para respuestas rápidas basadas en evidencia.", "q": "¿Cuál es la diferencia entre Elicit y Consensus?"}, {"a": "Elicit ofrece un plan gratuito Basic con búsqueda, resúmenes y chat con artículos ilimitados, aunque el uso de Research Agent y Reports es limitado. Los planes de pago son Pro (75 $ por usuario al mes, o 49 $ por usuario al mes con facturación anual a 588 $/año) y Scale (279 $ por usuario al mes, o 169 $ por usuario al mes con facturación anual a 2.028 $/año), con precios personalizados de Enterprise para necesidades mayores de filtrado y seguridad.", "q": "¿Es gratis Elicit?"}, {"a": "Elicit puede encargarse de las partes mecánicas de las revisiones sistemáticas: filtrado de artículos, extracción de datos y resumen. Reduce significativamente las horas de asistente de investigación necesarias para las revisiones de literatura. Sin embargo, el juicio experto para la evaluación de calidad y la interpretación de hallazgos todavía requiere investigadores humanos.", "q": "¿Puede Elicit reemplazar a un asistente de investigación?"}]$x$::jsonb
 WHERE slug = 'elicit' AND lang = 'es';

UPDATE tools SET best_for = $x$KI-Forschungsassistent für systematische Literaturrecherchen und Paper-Analysen$x$
 WHERE slug = 'elicit' AND lang = 'de';

UPDATE tools SET description = $x$Elicit ist eine KI-Forschungsplattform, die über 138 Mio. wissenschaftliche Paper und 545.000 klinische Studien durchsucht, strukturierte Daten extrahiert und Literaturrecherchen durchführt. Sie konzentriert sich nun auf den Elicit Research Agent und Routines, mit einer API und einem MCP-Server zur Integration von Suche und Extraktion in andere Tools.$x$
 WHERE slug = 'elicit' AND lang = 'de';

UPDATE tools SET description_long = $x$Elicit ist eine Research-Intelligence-Plattform für Akademiker, Evidenzsynthese-Teams und alle, die ernsthafte Literaturarbeit leisten. Sie durchsucht einen Korpus von mehr als 138 Millionen Papern und 545.000 klinischen Studien, fasst Ergebnisse zusammen, ermöglicht den Chat mit Papers und zieht spezifische Datenpunkte in strukturierte Tabellen.

Die Plattform ist längst über die einfache Papersuche hinausgewachsen. Elicit führte im Juli 2026 eine öffentliche API und einen MCP-Server ein und brachte im August 2026 den Elicit Research Agent heraus. Seit dem 30. September 2026 laufen Find Papers und Extract Data als Skills innerhalb des Research Agent, und mit Routines kann der Agent wiederkehrende Aufgaben nach Zeitplan ausführen und Updates per E-Mail versenden – als Ersatz für das bisherige Alerts-Tool, das zum 31. Oktober 2026 eingestellt wird. Auf der Firmen-Homepage wird aktuell angegeben, dass die Plattform von über 5 Millionen Forschenden genutzt wird.

Das zentrale kostenpflichtige Angebot dreht sich um systematische Literaturrecherche und Datenextraktion: Man kann Tausende Paper screenen, benutzerdefinierte Extraktionsspalten definieren und strukturierte Berichte mit überprüfbaren Quellen erstellen.

Die Preisgestaltung ist gestaffelt. Der Basic-Plan ist kostenlos und umfasst unbegrenzte Suche, unbegrenzte Zusammenfassungen, unbegrenzten Chat mit Papers, Quellenansicht und Zotero-Import, mit eingeschränkter Nutzung von Research Agent und Reports. Pro kostet 75 $ pro Nutzer und Monat bei monatlicher Abrechnung oder 49 $ pro Nutzer und Monat bei jährlicher Abrechnung (588 $/Jahr) und deckt das Screening von bis zu 5.000 Papern, 20 Extraktionsspalten und Berichte aus bis zu 135 Quellen ab, plus API-Zugang. Scale kostet 279 $ pro Nutzer und Monat bei monatlicher Abrechnung oder 169 $ pro Nutzer und Monat bei jährlicher Abrechnung (2.028 $/Jahr), mit etwa dem 5-fachen Nutzungsumfang von Pro, 30 Spalten, Abbildungsextraktion, Live-Zusammenarbeit, bis zu 200 Quellen und Admin-Kontrollen. Enterprise wird individuell bepreist und umfasst das Screening von bis zu 40.000 Papern, 40 Spalten, unbegrenzten API-Zugang sowie SSO/SAML/2FA.

Einschränkungen sind erwähnenswert: Das Tool ist auf akademische und klinische Literatur zugeschnitten und nicht auf allgemeine Websuche, ernsthafte Extraktions- und Screening-Umfänge erfordern einen kostenpflichtigen Plan, die monatliche Abrechnung ist deutlich teurer als ein Jahresabo, und wie bei jedem KI-Zusammenfassungstool müssen extrahierte Aussagen und Zitate weiterhin von Menschen überprüft werden.

Elicit eignet sich hervorragend für Forschende, Doktoranden, systematische Reviewer sowie F&E- oder klinische Teams, die sich schnell durch große Mengen an Evidenz arbeiten müssen, ohne die Möglichkeit zu verlieren, jede Aussage bis zu ihrer Quelle zurückzuverfolgen.$x$
 WHERE slug = 'elicit' AND lang = 'de';

