UPDATE tools SET faq = $x$[{"a": "Elicit est un assistant de recherche IA conçu pour les revues systématiques de littérature. Il recherche dans les bases de données académiques, filtre les articles selon leur pertinence et extrait des données structurées dans des tableaux — automatisant les parties les plus chronophages de la recherche académique. Il est utilisé par des chercheurs, des scientifiques et des équipes de synthèse de données probantes.", "q": "Qu'est-ce qu'Elicit ?"}, {"a": "Elicit est conçu pour les revues systématiques — il extrait des données structurées des articles dans des tableaux pour la méta-analyse. Consensus est conçu pour des questions-réponses rapides — il synthétise les résultats des articles en réponses en langage simple avec un indicateur de consensus. Elicit est destiné aux flux de recherche approfondie ; Consensus est destiné aux réponses rapides fondées sur des données probantes.", "q": "Quelle est la différence entre Elicit et Consensus ?"}, {"a": "Elicit propose un plan Basic gratuit avec recherche, résumés et chat avec les articles illimités, bien que l'usage du Research Agent et des Reports soit limité. Les plans payants sont Pro (75 $ par utilisateur et par mois, ou 49 $ par utilisateur et par mois facturé annuellement à 588 $/an) et Scale (279 $ par utilisateur et par mois, ou 169 $ par utilisateur et par mois facturé annuellement à 2 028 $/an), avec une tarification Enterprise personnalisée pour des besoins de filtrage et de sécurité plus importants.", "q": "Elicit est-il gratuit ?"}, {"a": "Elicit peut gérer les parties mécaniques des revues systématiques : filtrage des articles, extraction de données et résumé. Il réduit considérablement les heures d'assistanat de recherche nécessaires aux revues de littérature. Cependant, le jugement expert pour l'évaluation de la qualité et l'interprétation des résultats nécessite toujours des chercheurs humains.", "q": "Elicit peut-il remplacer un assistant de recherche ?"}]$x$::jsonb
 WHERE slug = 'elicit' AND lang = 'fr';

