UPDATE tools SET faq = $x$[{"a": "Elicit é um assistente de pesquisa de IA projetado para revisões sistemáticas de literatura. Ele busca em bases de dados acadêmicas, triagem artigos por relevância e extrai dados estruturados em tabelas — automatizando as partes mais demoradas da pesquisa acadêmica. É usado por pesquisadores, cientistas e equipes de síntese de evidências.", "q": "O que é Elicit?"}, {"a": "Elicit foi criado para revisões sistemáticas — ele extrai dados estruturados de artigos em tabelas para meta-análise. Consensus foi criado para perguntas e respostas rápidas — ele sintetiza descobertas de artigos em respostas em linguagem simples com um medidor de consenso. Elicit é para fluxos de trabalho de pesquisa aprofundada; Consensus é para respostas rápidas baseadas em evidências.", "q": "Qual é a diferença entre Elicit e Consensus?"}, {"a": "Elicit oferece um plano gratuito Basic com busca, resumos e chat com artigos ilimitados, embora o uso do Research Agent e de Reports seja limitado. Os planos pagos são Pro (US$ 75 por usuário por mês, ou US$ 49 por usuário por mês na cobrança anual, totalizando US$ 588/ano) e Scale (US$ 279 por usuário por mês, ou US$ 169 por usuário por mês na cobrança anual, totalizando US$ 2.028/ano), com preço Enterprise personalizado para necessidades maiores de triagem e segurança.", "q": "Elicit é gratuito?"}, {"a": "Elicit pode cuidar das partes mecânicas das revisões sistemáticas: triagem de artigos, extração de dados e resumo. Ele reduz significativamente as horas de assistente de pesquisa necessárias para revisões de literatura. No entanto, o julgamento especializado para avaliação de qualidade e interpretação de descobertas ainda exige pesquisadores humanos.", "q": "O Elicit pode substituir um assistente de pesquisa?"}]$x$::jsonb
 WHERE slug = 'elicit' AND lang = 'pt';

