UPDATE tools SET faq = $x$[{"q": "O que é o Consensus AI?", "a": "Consensus é um mecanismo de pesquisa acadêmica com IA que vasculha a literatura revisada por pares. Ele extrai descobertas-chave, pode mostrar o nível de concordância entre estudos no estilo consensus meter e fornece respostas citadas, com capacidades como Deep Search e recursos mais recentes de workspace de IA, como Skills e uma Research Gaps Matrix."}, {"q": "O Consensus é gratuito?", "a": "O Consensus tem um plano gratuito que inclui busca básica de artigos, 10 mensagens Pro por mês e até 3 Deep reviews por mês. O Pro custa US$ 20/mês, ou US$ 144/ano se cobrado anualmente (cerca de US$ 12/mês), e inclui mensagens Pro ilimitadas, 15 Deep reviews por mês e 500 usos de API/MCP por mês. Um plano Deep custa US$ 65/mês, ou US$ 540/ano se cobrado anualmente (cerca de US$ 45/mês), com 200 Deep reviews e 2.000 usos de API/MCP por mês. Estudantes, professores e profissionais clínicos nos EUA podem obter até 40% de desconto. Preços para Team e Enterprise estão disponíveis mediante solicitação."}, {"q": "Qual é a diferença entre Consensus e Google Scholar?", "a": "O Google Scholar é um índice de busca - ele encontra artigos, mas você precisa lê-los por conta própria. O Consensus usa IA para extrair descobertas-chave dos artigos e sintetizá-las em respostas diretas, com um recurso de consensus meter mostrando o quanto de concordância existe entre os estudos, o que pode economizar tempo de leitura."}]$x$::jsonb
 WHERE slug = 'consensus' AND lang = 'pt';

