UPDATE tools SET faq = $x$[{"q": "Was ist Claude Design?", "a": "Claude Design ist eine integrierte Claude-Funktion, die UI-Mockups, Präsentationen und visuelle Prototypen per Konversation erzeugt und innerhalb des Claude-Chats, in Claude Code oder im Artifacts-Tab funktioniert, ohne separate Design-Software."}, {"q": "Was kostet Claude Design?", "a": "Claude Design hat keinen separaten Preis und ist in jedem Claude-Plan enthalten, einschließlich Free. Kostenpflichtige Pläne sind Claude Pro (20 $/Monat bzw. 17 $/Monat bei jährlicher Abrechnung), Max-Pläne (ab 100 $/Monat), Team Standard (25 $/Platz/Monat, 20 $/Platz/Monat bei jährlicher Abrechnung), Team Premium (125 $/Platz/Monat, 100 $/Platz/Monat bei jährlicher Abrechnung) und Enterprise (20 $/Platz/Monat bei jährlicher Abrechnung zuzüglich Nutzung zu API-Tarifen). Die Nutzung zählt zu den gemeinsamen Nutzungslimits jedes Plans."}, {"q": "Kann Claude Design nach Figma oder Code exportieren?", "a": "Claude Design exportiert als .zip, PDF, PPTX, Google-Slides-Datei oder eigenständiges HTML und kann Output direkt an verbundene Tools senden, darunter Adobe, Canva, Gamma, HubSpot, Lovable, Miro, Netlify, Replit, v0, Vercel und Wix, oder via /design-sync oder /design an Claude Code übergeben."}, {"q": "Welche Arten von Designs kann Claude Design erstellen?", "a": "Claude Design erstellt UI-Mockups, Landingpages, Präsentationsfolien und Marketingmaterialien. Es kann Markenstile aus bestehenden Assets extrahieren und konsistent anwenden."}]$x$::jsonb
