UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Claude Design ?", "a": "Claude Design est une fonctionnalité intégrée à Claude qui génère des maquettes d'interface, des présentations et des prototypes visuels par conversation, fonctionnant dans le chat Claude, Claude Code, ou l'onglet Artifacts, sans logiciel de conception séparé."}, {"q": "Combien coûte Claude Design ?", "a": "Claude Design n'a pas de tarif distinct et est incluse dans chaque plan Claude, y compris Free. Les plans payants sont Claude Pro (20 $/mois, ou 17 $/mois facturé annuellement), les plans Max (à partir de 100 $/mois), Team Standard (25 $/poste/mois, 20 $/poste/mois facturé annuellement), Team Premium (125 $/poste/mois, 100 $/poste/mois facturé annuellement), et Enterprise (20 $/poste/mois facturé annuellement plus l'utilisation aux tarifs de l'API). L'utilisation compte dans les limites d'utilisation partagées de chaque plan."}, {"q": "Claude Design peut-il exporter vers Figma ou du code ?", "a": "Claude Design exporte sous forme de fichier .zip, PDF, PPTX, fichier Google Slides, ou HTML autonome, et peut envoyer directement le résultat vers des outils connectés incluant Adobe, Canva, Gamma, HubSpot, Lovable, Miro, Netlify, Replit, v0, Vercel et Wix, ou transmettre le relais à Claude Code via /design-sync ou /design."}, {"q": "Quels types de designs Claude Design peut-il créer ?", "a": "Claude Design crée des maquettes d'interface, des pages d'atterrissage, des diapositives de présentation et des supports marketing. Il peut extraire les styles de marque à partir d'éléments existants et les appliquer de manière cohérente."}]$x$::jsonb
