UPDATE tools SET faq = $x$[{"q": "O que é o Claude Design?", "a": "Claude Design é um recurso nativo do Claude que gera mockups de UI, apresentações e protótipos visuais por meio de conversa, funcionando dentro do chat do Claude, do Claude Code, ou da aba Artifacts, sem necessidade de software de design separado."}, {"q": "Quanto custa o Claude Design?", "a": "O Claude Design não tem preço separado e está incluído em todos os planos do Claude, incluindo o Free. Os planos pagos são o Claude Pro ($20/mês, ou $17/mês com cobrança anual), os planos Max (a partir de $100/mês), o Team Standard ($25/assento/mês, $20/assento/mês com cobrança anual), o Team Premium ($125/assento/mês, $100/assento/mês com cobrança anual), e o Enterprise ($20/assento/mês com cobrança anual mais uso cobrado nas tarifas de API). O uso conta para os limites de uso compartilhados de cada plano."}, {"q": "O Claude Design pode exportar para Figma ou código?", "a": "O Claude Design exporta como .zip, PDF, PPTX, arquivo do Google Slides, ou HTML independente, e pode enviar o resultado diretamente para ferramentas conectadas, incluindo Adobe, Canva, Gamma, HubSpot, Lovable, Miro, Netlify, Replit, v0, Vercel e Wix, ou repassar o trabalho ao Claude Code via /design-sync ou /design."}, {"q": "Que tipos de designs o Claude Design pode criar?", "a": "O Claude Design cria mockups de UI, landing pages, slides de apresentação e materiais de marketing. Ele consegue extrair estilos de marca a partir de ativos existentes e aplicá-los de forma consistente."}]$x$::jsonb
