 WHERE slug = 'figma-ai' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Figma AI includes AI-generated layers and designs from text prompts, AI rename for layers, first draft generation, and prototype generation via Figma Make. AI credits are also included on the free Starter plan (150/day, up to 500/month), with larger allotments on paid plans.", "q": "What AI features does Figma have?"}, {"a": "No. Canva and Figma serve different purposes. Canva is for creating marketing content and presentations. Figma is for designing UI/UX interfaces and product prototypes. Designers use Figma; content creators use Canva.", "q": "Can Canva replace Figma?"}, {"a": "Canva is significantly easier for beginners — it's designed for non-designers with drag-and-drop simplicity. Figma has a steeper learning curve and is designed for professional designers. For quick graphics, start with Canva.", "q": "Which is better for beginners — Canva or Figma?"}]$x$::jsonb
 WHERE slug = 'figma-ai' AND lang = 'en';

