UPDATE tools SET cons = ARRAY[$x$Le passage à des crédits IA mesurés a mis fin à la bêta gratuite illimitée, rendant un usage intensif désormais payant$x$, $x$Le palier gratuit Starter est strictement plafonné à 150 crédits/jour et 500/mois, limitant l'expérimentation soutenue$x$, $x$Le dépassement de l'allocation mensuelle est un complément payant, rendant les coûts plus difficiles à prévoir$x$, $x$Les résultats de Make et First Draft sont des points de départ qui nécessitent encore un affinage manuel par un designer$x$, $x$La tarification des sièges Professional est nettement plus élevée en facturation mensuelle (20 $/15 $/5 $) qu'en facturation annuelle (16 $/12 $/3 $), le tarif réduit nécessitant donc un engagement d'un an$x$]::text[]
 WHERE slug = 'figma-ai' AND lang = 'fr';

