UPDATE tools SET faq = $x$[{"a": "Figma AI inclut des calques et designs générés par IA à partir d'invites textuelles, le renommage de calques par IA, la génération de premiers brouillons, et la génération de prototypes via Figma Make. Des crédits IA sont également inclus dans l'offre gratuite Starter (150/jour, jusqu'à 500/mois), avec des allocations plus importantes sur les offres payantes.", "q": "Quelles fonctionnalités d'IA Figma propose-t-il ?"}, {"a": "Non. Canva et Figma répondent à des besoins différents. Canva sert à créer du contenu marketing et des présentations. Figma sert à concevoir des interfaces UI/UX et des prototypes de produits. Les designers utilisent Figma ; les créateurs de contenu utilisent Canva.", "q": "Canva peut-il remplacer Figma ?"}, {"a": "Canva est nettement plus facile pour les débutants : il est conçu pour les non-designers avec une simplicité de type glisser-déposer. Figma a une courbe d'apprentissage plus raide et est conçu pour les designers professionnels. Pour des graphiques rapides, commencez par Canva.", "q": "Lequel est préférable pour les débutants, Canva ou Figma ?"}]$x$::jsonb
 WHERE slug = 'figma-ai' AND lang = 'fr';

UPDATE tools SET best_for = $x$Design de UI/UX, agentes de IA no canvas, ferramentas de imagem, entrada por voz, texto em trajeto$x$
 WHERE slug = 'figma-ai' AND lang = 'pt';

UPDATE tools SET description = $x$Figma AI é o conjunto de recursos de IA integrados ao Figma, regido por um sistema compartilhado de créditos de IA que mede o uso no Figma Make, First Draft, geração de imagens e mais. Todo plano inclui uma cota mensal de créditos, de 500 no nível gratuito Starter até 4.250 no Enterprise Full.$x$
 WHERE slug = 'figma-ai' AND lang = 'pt';

UPDATE tools SET description_long = $x$Figma AI não é um produto independente, mas uma camada de recursos generativos incorporada ao editor de design do Figma. Ele cobre fluxos de prompt para design e prompt para protótipo, geração e edição de imagens por IA, reescrita e tradução de texto, e o First Draft para transformar um briefing em um layout inicial. O recurso principal é o Figma Make, que transforma um prompt escrito em um protótipo interativo funcional e pode se conectar a um backend Supabase para criar aplicativos funcionais. A partir de 6 de outubro de 2026, o agente Figma no canvas e o conjunto Weave de fluxos de trabalho de IA para imagens, vídeo e áudio saíram do beta aberto para disponibilidade geral e agora consomem créditos de IA como o restante do conjunto de recursos de IA.

O Figma tirou esses recursos de IA de um beta gratuito e, na prática, ilimitado, e os colocou em uma economia de créditos de IA medida, compartilhada entre todas as suas ferramentas de IA. Os créditos de IA estão disponíveis em todos os planos, incluindo o nível gratuito Starter, embora o agente Figma tenha disponibilidade limitada nele.

Em termos de capacidade, isso consolida a maior parte da proposta de IA do Figma em um só lugar: gerar um primeiro rascunho, iterar com o Make, produzir ou editar imagens, reescrever e traduzir textos, conversar com o agente no canvas e repassar para arquivos de design reais. Os créditos são consumidos por ação, embora o custo exato por ação não seja divulgado.

O plano gratuito Starter tem um limite de 150 créditos por dia e 500 por mês, com rascunhos ilimitados. As licenças Professional custam US$ 20 (Full), US$ 15 (Dev) e US$ 5 (Collab) por mês na cobrança mensal, ou US$ 16, US$ 12 e US$ 3 por mês na cobrança anual; uma licença Full adiciona 3.000 créditos de IA por mês, enquanto as licenças Dev e Collab adicionam 500 cada uma. As licenças Organization custam US$ 55 (Full), US$ 25 (Dev) e US$ 5 (Collab) por mês, com cobrança anual, adicionando até 3.500 créditos. As licenças Enterprise custam US$ 90 (Full), US$ 35 (Dev) e US$ 5 (Collab) por mês, com cobrança anual, adicionando até 4.250 créditos. Além da cota mensal, uso adicional está disponível como complemento de créditos pré-pago ou por assinatura; esses multiplicadores de créditos complementares foram aumentados em 25 de agosto de 2026, pelo mesmo preço.

A principal limitação é exatamente essa medição: usuários intensivos de IA podem esgotar os créditos rapidamente, e o limite diário no nível gratuito dificulta a experimentação sustentada. A qualidade da saída do Make e do First Draft é um ponto de partida, não um design finalizado, e ainda precisa da mão de um designer.

Figma AI faz mais sentido para equipes que já vivem no Figma e querem a IA incorporada aos seus arquivos existentes, em vez de uma ferramenta separada. Se você raramente usa IA, a cota gratuita pode ser suficiente; se a IA é central no seu fluxo de trabalho, reserve orçamento para um nível pago e possível excedente, e considere se você pode se comprometer com a cobrança anual para obter a taxa mais baixa do Professional.$x$
 WHERE slug = 'figma-ai' AND lang = 'pt';

UPDATE tools SET pros = ARRAY[$x$Profundamente integrado ao editor Figma, de modo que a saída da IA chega diretamente aos seus arquivos de design sem etapa de exportação/importação$x$, $x$O Figma Make pode transformar um prompt em um protótipo interativo e se conectar a um backend Supabase para criar aplicativos funcionais$x$, $x$Cobre uma ampla gama de tarefas: primeiros rascunhos, geração e edição de imagens, reescrita, tradução e o conjunto Weave, agora em disponibilidade geral, para fluxos de trabalho de imagem, vídeo e áudio$x$, $x$O plano gratuito Starter inclui créditos mensais de IA (150/dia, até 500/mês) para experimentar os recursos$x$, $x$Um servidor Figma MCP e conectores permitem que agentes e ferramentas de IA trabalhem diretamente com arquivos do Figma$x$]::text[]
 WHERE slug = 'figma-ai' AND lang = 'pt';

UPDATE tools SET cons = ARRAY[$x$A mudança para créditos de IA medidos encerrou o beta gratuito e ilimitado, então o uso intenso agora custa dinheiro$x$, $x$O nível gratuito Starter tem um limite rígido de 150 créditos/dia e 500/mês, limitando a experimentação sustentada$x$, $x$O excedente além da cota mensal é um complemento pago, tornando os custos mais difíceis de prever$x$, $x$As saídas do Make e do First Draft são pontos de partida que ainda precisam de refinamento manual por um designer$x$, $x$O preço das licenças Professional é consideravelmente mais alto na cobrança mensal (US$ 20/US$ 15/US$ 5) do que na cobrança anual (US$ 16/US$ 12/US$ 3), então a taxa mais baixa exige um compromisso de um ano$x$]::text[]
 WHERE slug = 'figma-ai' AND lang = 'pt';

UPDATE tools SET choose_if = $x$["🎨 Sua equipe já trabalha diariamente no Figma e quer a IA dentro dos arquivos existentes", "🚀 Você quer ir de um prompt a um protótipo interativo conectado ao Supabase", "💡 Você só precisa de ajuda ocasional de IA e consegue se manter dentro da cota gratuita de créditos", "🖼️ Você valoriza a geração de imagens, reescrita e tradução integradas em vez de uma ferramenta separada"]$x$::jsonb
 WHERE slug = 'figma-ai' AND lang = 'pt';

UPDATE tools SET faq = $x$[{"a": "O Figma AI inclui camadas e designs gerados por IA a partir de prompts de texto, renomeação automática de camadas por IA, geração de primeiro rascunho e geração de protótipos via Figma Make. Os créditos de IA também estão incluídos no plano gratuito Starter (150/dia, até 500/mês), com cotas maiores nos planos pagos.", "q": "Quais recursos de IA o Figma possui?"}, {"a": "Não. Canva e Figma atendem a propósitos diferentes. O Canva serve para criar conteúdo de marketing e apresentações. O Figma serve para projetar interfaces de UI/UX e protótipos de produtos. Designers usam o Figma; criadores de conteúdo usam o Canva.", "q": "O Canva pode substituir o Figma?"}, {"a": "O Canva é significativamente mais fácil para iniciantes — foi projetado para não designers, com simplicidade de arrastar e soltar. O Figma tem uma curva de aprendizado mais acentuada e é voltado para designers profissionais. Para gráficos rápidos, comece com o Canva.", "q": "Qual é melhor para iniciantes — Canva ou Figma?"}]$x$::jsonb
 WHERE slug = 'figma-ai' AND lang = 'pt';
